        "leadOriginal": "알파 메탈러지컬 리소시스는 미국 버지니아·웨스트버지니아에서 원료탄(제철용 석탄)을 캐 국내외 철강회사에 파는 회사다. 피치솔루션즈 산하 BMI가 인도·중국의 수입 수요 증가를 근거로 2026년 원료탄 가격 전망을 톤당 180달러에서 190달러로 올리는 등 원료탄 값이 뛰면서 주가가 함께 올랐다. 8월7일 발표한 2분기 실적에서 매출(4억9,150만달러)이 시장 예상치를 웃돌았고, 케네스 코티스 이사가 8월21일과 25일 잇달아 자사주를 사들인 점(각각 약 316만달러, 108만달러)도 투자심리를 자극했다. 다만 같은 실적 발표에서 회사는 2026년 출하량 전망을 낮추고 비용 전망은 높였으며, 애널리스트들은 오히려 목표주가와 이익 전망치를 낮추고 있어 주가 상승과 엇갈리는 신호도 함께 나온다."
