        "status": "done",
        "company": "델 테크놀로지스는 미국 텍사스에 본사를 둔 컴퓨터 하드웨어 회사로, 개인이 쓰는 노트북·데스크톱 같은 PC(고객솔루션그룹)와 기업들이 데이터를 처리·저장할 때 쓰는 서버·저장장치(인프라솔루션그룹)를 만들어 판다. 최근에는 인공지능(AI) 모델을 학습·구동하는 데 쓰이는 대형 'AI서버'를 데이터센터 운영업체와 대기업에 공급해 돈을 벌고 있다. 주요 고객은 일반 소비자보다는 기업·정부기관 같은 상업용 고객이 많다. 요즘 주목받는 이유는 AI서버 수요가 폭발적으로 늘면서 2026년 5월 1일 마감된 1분기 매출이 전년보다 87.5% 급증하는 등 실적이 크게 좋아졌고, 이에 따라 주가도 올해 들어 큰 폭으로 올랐기 때문이다. 다만 최근 실적발표(9월 1일 예정)를 앞두고 주가가 크게 오른 뒤라 밸류에이션 부담에 대한 시각도 함께 나오고 있다.",
        "lead": "델 테크놀로지스는 PC와 기업용 서버·저장장치를 만들어 파는 컴퓨터 하드웨어 회사로, 최근에는 인공지능(AI) 데이터센터에 들어가는 대형 AI서버 판매로 실적이 급성장하고 있다. 2026년 5월 1일 마감된 1분기(FY2027 1Q) 매출은 438억 달러로 전년 대비 87.5%, 영업이익은 213.8% 늘었고, 신한투자증권에 따르면 AI서버 매출만 757% 급증하며 수주잔고(백로그)가 513억 달러에 달했다. 이런 실적 서프라이즈에 힘입어 8월 24일 에버코어 ISI는 AI서버 수요가 공급을 웃돈다며 목표주가 550달러(약 25% 추가 상승 여력)를 제시했다. 다만 8월 31일 도이체방크는 목표주가 480달러의 보유(Hold) 의견을 내며 밸류에이션 부담을 시사했고, 실적 발표(9월 1일 예정)를 앞두고 주가는 조정 국면에 들어섰다는 기술적 분석도 나온다.",
