        "ticker": "GWRE",
        "company": "가이드와이어 소프트웨어는 보험회사들이 업무에 쓰는 소프트웨어를 만들어 파는 회사다. 주로 자동차보험·주택보험 같은 손해보험(P&C보험) 회사에게 보험상품을 설계하고, 보험료를 청구하고, 사고접수와 보상금 지급까지 처리하는 클라우드 기반 시스템을 제공한다. 돈은 이 시스템을 쓰는 보험사들이 매년 내는 구독료로 번다 - 넷플릭스 구독료처럼 보험사가 해마다 이용료를 지불하는 구조다. 전세계 43개국 570곳 넘는 보험사가 가이드와이어 제품을 쓰고 있다(Guidewire 공식 자료 기준). 최근에는 보험업무에 AI 에이전트를 붙여 서류검토·심사 같은 일을 자동으로 처리해주는 신제품(2026년 8월 'Qusar' 릴리스, 에이전틱 프레임워크)을 내놓으면서 AI 관련 인슈어테크(보험+기술) 종목으로도 주목받고 있다.",
        "lead": "가이드와이어 소프트웨어는 보험사에 클라우드 기반 보험업무 소프트웨어를 구독형으로 판매하는 회사다. 6월 4일 발표한 2026 회계연도 3분기(4월 마감) 실적에서 매출이 증가했고, 연간반복매출(ARR)도 11억4,700만 달러로 19% 증가해 자체 가이던스 상단을 웃돌았다. 이 호실적을 근거로 회사는 4분기 매출·영업이익 가이던스를 상향했고, 애널리스트들도 뒤이어 목표주가를 올렸다 - 구겐하임은 8월 들어 목표주가를 180달러에서 210달러로 높였다. 여기에 8월 3일 보험업무용 AI 에이전트 신제품('Qusar') 출시 소식까지 겹치며 주가는 상승세를 이어갔다.",
