        "leadOriginal": "네비우스 그룹은 엔비디아 GPU 기반 AI 클라우드를 빅테크에 임대해주는 네덜란드계 네오클라우드 기업으로, 최근 6개월 주가가 120.33% 급등했다. 8월 13일 발표한 2분기 매출이 5억8,200만 달러로 전년동기 대비 454% 늘며 시장 예상을 웃돌았고, 메타·마이크로소프트와 맺은 최대 460억 달러 규모의 장기 AI 인프라 공급계약이 실적의 뒷받침이 되고 있다. 여기에 7월 20일 엔비디아가 지분 9.3%를 보유하고 있다는 사실이 공시되며 주가가 시간외 3% 오르는 등 대형 투자자들의 관심도 확인됐다. 다만 8월 22일 50억 달러 규모 전환사채 발행이 확정되며 희석 우려가 불거졌고, 이 여파로 최근 3개월 절대 수익률은 오히려 -16.89%로 조정을 받는 등 급등 이후 밸류에이션과 자금조달 방식을 둘러싼 논쟁이 이어지고 있다."
