        "ticker": "SYRE",
        "company": "스파이어 테라퓨틱스(Spyre Therapeutics)는 아직 팔 수 있는 약이 하나도 없는 임상 단계 바이오텍 회사입니다. 그래서 매출은 0달러이고, 돈을 버는 대신 계속 손실을 내며 신약 후보물질을 개발하고 있습니다. 이 회사가 만드는 약은 크론병·궤양성 대장염 같은 염증성 장질환(IBD)과 류마티스 관절염 같은 자가면역질환을 치료하는 항체 신약이고, 최종 고객은 이런 병을 앓는 환자와 이들을 치료하는 병원·제약회사(라이선스 파트너)입니다. 최근 임상 2상(신약이 실제 환자에게 효과가 있는지 확인하는 중간 단계 시험) SKYLINE에서 궤양성 대장염 후보물질 SPY001·SPY002가 좋은 결과를 내면서 시장의 관심이 크게 쏠렸습니다. 반면 8월 25일 발표한 류마티스 관절염 후보물질 SPY072는 내부 기준을 넘지 못해 단독 개발을 접기로 하면서 주가가 흔들렸습니다. 아직 매출이 없는 만큼 앞으로 나오는 임상시험 결과 하나하나가 주가를 크게 움직이는 재료입니다.",
