          "why": "이 소그룹은 'AI 지출'로 설명되지 않는 상승을 정직하게 분리한 것이다. ANF는 8월 26일 발표한 FY2026 2분기 조정 주당순이익이 4.17달러로 예상치 1.99달러를 두 배 넘게 웃돌았고, 매출은 13억 달러(전년비 +5%), 발표 당일 장 마감 45분 전 기준 34.8% 급등했다 — 다만 이익 급증의 큰 부분은 미국 대법원이 IEEPA(국제비상경제권법) 관세를 위법으로 판단해 받은 약 1억 달러 관세 환급금이라는 일회성 요인이다. IT(가트너)는 2분기 계약가치(고객 구독 계약의 반복 매출 총액) 성장률이 2%로 재가속했다고 밝히고 2026년 조정 주당순이익 전망을 14달러 이상으로 상향했으며, 골드만삭스가 목표주가를 162→181달러, UBS가 164→196달러로 올렸고 8월 8일 Zacks리서치가 투자의견을 '보유'에서 '적극매수'로 상향, 8월 25일자 Zacks 기사는 최근 3개월 28% 상승을 전했다. GWRE는 3분기 말 연간반복매출이 11억4,700만 달러로 전년 10억4,100만 달러 대비 19% 늘어 가이던스(11억4,400만~11억5,000만 달러)를 웃돌았고 4분기 연간반복매출 12억2,900만~12억3,700만 달러를 제시하며 FY2026 가이던스를 상향, 구겐하임이 8월 목표주가를 180→210달러로 올렸다. AUGO는 8월 5일 2분기 순매출 3억3,600만 달러(전년 1억9,040만 달러 대비 +76%), 순이익 2억1,770만 달러, 조정 EBITDA 1억9,670만 달러(전년비 +85%, 마진 59%)를 기록했는데 순이익 중 1억2,600만 달러가 금 헤지 미실현 평가이익이고 국제 금값이 8월 한 주 7% 넘게 올랐다. 반대 근거: ANF의 관세 환급금과 AUGO의 헤지 평가이익은 모두 다음 분기에 반복되지 않을 수 있는 항목이다 — 이 소그룹의 상승은 '지속되는 수요'보다 '한 번의 숫자'에 기댄 부분이 있다.",
