          "plainKo": "AI가 회사 안의 데이터를 마음대로 뒤지고 일을 대신 처리하게 되면, '누가 무엇에 접근해도 되는지'를 관리하는 일이 훨씬 중요해집니다. 그래서 보안 회사들의 일감이 AI 도입 속도만큼 같이 늘어납니다.",
